// ─── File: SpringPatternsDemo.java ───
package com.bank.springpatterns;

import java.lang.reflect.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SpringPatternsDemo {
    private static final Logger log = Logger.getLogger(SpringPatternsDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // FACTORY + SINGLETON: container builds and caches one TransferService
        MiniContainer container = new MiniContainer();
        TransferService raw = container.getBean(TransferService.class);
        TransferService same = container.getBean(TransferService.class);
        log.info(() -> "Singleton? same instance = " + (raw == same));

        // PROXY: wrap the service so transfer() runs inside a transaction
        TransferService service = TransactionalProxy.wrap(raw, TransferService.class);

        // OBSERVER: listeners react to a completed transfer
        EventPublisher publisher = new EventPublisher();
        publisher.subscribe(evt -> log.info(() -> "AUDIT : " + evt));
        publisher.subscribe(evt -> log.info(() -> "SMS   : Dear Rajesh, " + evt));
        raw.setPublisher(publisher);

        // TEMPLATE METHOD + STRATEGY: query with a RowMapper, sort with Comparator
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        MiniJdbcTemplate jdbc = new MiniJdbcTemplate();
        List<Account> accounts = jdbc.query("SELECT * FROM accounts",
            row -> new Account(row[0], row[1], new BigDecimal(row[2])));
        accounts.sort(Comparator.comparing(Account::getBalance)); // STRATEGY
        accounts.forEach(a -> log.info(() -> a.getAccountId() + " bal=" + a.getBalance()));
    }
}

// ─── FACTORY + SINGLETON (mini Spring container) ───
class MiniContainer {
    private final Map<Class<?>, Object> singletons = new HashMap<>();
    @SuppressWarnings("unchecked")
    <T> T getBean(Class<T> type) {
        return (T) singletons.computeIfAbsent(type, t -> {
            try { return t.getDeclaredConstructor().newInstance(); }
            catch (Exception e) { throw new RuntimeException(e); }
        });
    }
}

// ─── PROXY (like @Transactional) ───
class TransactionalProxy {
    @SuppressWarnings("unchecked")
    static <T> T wrap(T target, Class<T> iface) {
        return (T) Proxy.newProxyInstance(
            iface.getClassLoader(), new Class<?>[]{iface},
            (p, method, args) -> {
                Logger.getLogger("TX").info("BEGIN TX " + method.getName());
                try {
                    Object r = method.invoke(target, args);
                    Logger.getLogger("TX").info("COMMIT TX " + method.getName());
                    return r;
                } catch (Exception e) {
                    Logger.getLogger("TX").severe("ROLLBACK TX " + method.getName());
                    throw e;
                }
            });
    }
}

// ─── TEMPLATE METHOD (like JdbcTemplate) + STRATEGY (RowMapper) ───
interface RowMapper<T> { T map(String[] row); }
class MiniJdbcTemplate {
    <T> List<T> query(String sql, RowMapper<T> mapper) {
        // skeleton: connect → fetch → map → close (fixed); mapper is the variable step
        String[][] rows = { {"SAV2001","Rajesh Kumar","950000"},
                            {"CUR3001","Priya Sharma","300000"} };
        List<T> out = new ArrayList<>();
        for (String[] r : rows) out.add(mapper.map(r));
        return out;
    }
}

// ─── OBSERVER (like ApplicationEvent) ───
interface TransferListener { void onEvent(String event); }
class EventPublisher {
    private final List<TransferListener> listeners = new ArrayList<>();
    void subscribe(TransferListener l) { listeners.add(l); }
    void publish(String event) { listeners.forEach(l -> l.onEvent(event)); }
}

// ─── Service behind an interface so the Proxy can wrap it ───
interface TransferService { void transfer(String from, String to, BigDecimal amt); void setPublisher(EventPublisher p); }
class TransferServiceImpl implements TransferService {
    private EventPublisher publisher;
    public void setPublisher(EventPublisher p) { this.publisher = p; }
    public void transfer(String from, String to, BigDecimal amt) {
        if (publisher != null) publisher.publish("TRANSFER " + from + "->" + to + " Rs." + amt);
    }
}

class Account {
    private final String accountId, holderName; private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    String getAccountId() { return accountId; } String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
